// Writes Runtime/World/Fish/EagleRayData.cs from src/world/fish/EagleRayData.js (the baked spotted eagle ray, itself generated by
// tools/creatures/bake-eagle-ray.mjs from assets/eagle-ray.glb): the two levels of detail as base64 strings and the numbers
// CreatureGeometry.eagleRayGeometry needs.    node unity/tools/dump-eagle-ray.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve( path.dirname( fileURLToPath( import.meta.url ) ), '../..' );
const { EAGLE_RAY } = await import( root + '/src/world/fish/EagleRayData.js' );
const num = ( v ) => String( v );
const chunk = ( s ) => s.match( /.{1,120}/g ).map( ( l ) => `\t\t\t"${ l }"` ).join( ' +\n' );
const cs = `// GENERATED by unity/tools/dump-eagle-ray.mjs from src/world/fish/EagleRayData.js (itself baked by tools/creatures/bake-eagle-ray.mjs from
// assets/eagle-ray.glb): do not edit. The spotted eagle ray in the fish frame, two levels of detail as base64: uint32 vertex count, uint32
// triangle count, then per vertex int16 x y z (/ scale), uint8 part, int8 w (+1 back, -1 belly), then uint16 indices.
namespace Tidewater.World.Fish
{
	public static class EagleRayData
	{
		public const double scale = ${ num( EAGLE_RAY.scale ) };
		public const double whipRoot = ${ num( EAGLE_RAY.meta.whipU.root ) }, whipK = ${ num( EAGLE_RAY.meta.whipU.k ) };
		public static readonly double[][] eyes = { ${ EAGLE_RAY.meta.eyes.map( ( e ) => 'new[] { ' + e.join( ', ' ) + ' }' ).join( ', ' ) } };
		public static readonly string[] lods =
		{
${ EAGLE_RAY.lods.map( ( l ) => chunk( l ) ).join( ',\n' ) }
		};
	}
}
`;
const dest = path.join( root, 'unity/Assets/Tidewater/Runtime/World/Fish/EagleRayData.cs' );
fs.writeFileSync( dest, cs );
console.log( 'wrote', dest, cs.length, 'bytes' );
